M["modules/scanner.lua"] = [====[
-- MilfaCheatHUB • dynamic game scanner
-- Reads replicated client state and Workspace without fixed egg coordinates.

local Scanner = {}
Scanner.__index = Scanner

local function safeRequire(instance)
    if not instance then return nil end
    local ok, value = pcall(require, instance)
    return ok and value or nil
end

local function findPath(root, path)
    local current = root
    for segment in string.gmatch(path, "[^%.]+") do
        current = current and current:FindFirstChild(segment)
    end
    return current
end

function Scanner.new(config)
    local self = setmetatable({}, Scanner)
    self.Config = config
    self.Players = game:GetService("Players")
    self.RS = game:GetService("ReplicatedStorage")
    self.Workspace = game:GetService("Workspace")
    self.Player = self.Players.LocalPlayer

    self.EggState = safeRequire(findPath(self.RS, "Client.EggState"))
    self.PlotState = safeRequire(findPath(self.RS, "Client.PlotState"))
    self.Save = safeRequire(findPath(self.RS, "Shared.Save"))

    local library = self.RS:FindFirstChild("Library")
    local clientLibrary = library and library:FindFirstChild("Client")
    self.EggCmds = self.EggState or safeRequire(clientLibrary and clientLibrary:FindFirstChild("EggCmds"))
    self.PlotCmds = self.PlotState or safeRequire(clientLibrary and clientLibrary:FindFirstChild("PlotCmds"))
    return self
end

function Scanner:GetSave()
    if not self.Save then
        self.Save = safeRequire(findPath(self.RS, "Shared.Save"))
    end
    local save = self.Save
    if type(save) == "table" then
        if type(save.Get) == "function" then
            local ok, value = pcall(save.Get)
            if ok and type(value) == "table" then return value end
        end
        return save
    end
    return nil
end

function Scanner:GetCharacter()
    return self.Player.Character
end

function Scanner:GetRoot()
    local character = self:GetCharacter()
    return character and character:FindFirstChild("HumanoidRootPart")
end

function Scanner:GetEggFolder()
    return self.Workspace:FindFirstChild("AreaEggSlotsClient")
        or self.Workspace:FindFirstChild("Eggs")
end

function Scanner:ReadEggSnapshot()
    if type(self.EggCmds) ~= "table" then return nil end
    for _, methodName in ipairs({"ReadFieldEggs", "GetAreaEggSnapshot", "RequestAreaEggSnapshot"}) do
        local method = self.EggCmds[methodName]
        if type(method) == "function" then
            local ok, result = pcall(method)
            if ok and type(result) == "table" then
                return result.Records or result
            end
        end
    end
    return nil
end

function Scanner:GetEggInstance(record)
    if record.Instance and record.Instance.Parent then return record.Instance end
    local folder = self:GetEggFolder()
    if not folder or not record.Uid then return nil end
    return folder:FindFirstChild(tostring(record.Uid))
end

function Scanner:GetEggPosition(record)
    local frame = record.BottomCFrame or record.CFrame
    if typeof(frame) == "CFrame" then return frame.Position end
    if typeof(record.Position) == "Vector3" then return record.Position end

    local instance = self:GetEggInstance(record)
    if not instance then return nil end
    if instance:IsA("BasePart") then return instance.Position end
    if instance:IsA("Model") then return instance:GetPivot().Position end
    local part = instance:FindFirstChildWhichIsA("BasePart", true)
    return part and part.Position or nil
end

function Scanner:GetEggs()
    local records, seen = {}, {}
    local snapshot = self:ReadEggSnapshot()

    if type(snapshot) == "table" then
        for key, record in pairs(snapshot) do
            if type(record) == "table" then
                local uid = record.Uid or record.UID or record.Id
                if uid == nil and type(key) == "string" then uid = key end
                if uid then
                    record.Uid = uid
                    seen[tostring(uid)] = true
                    records[#records + 1] = record
                end
            end
        end
    end

    local folder = self:GetEggFolder()
    if folder then
        for _, instance in ipairs(folder:GetChildren()) do
            local uid = instance:GetAttribute("Uid") or instance:GetAttribute("Id") or instance.Name
            if not seen[tostring(uid)] then
                records[#records + 1] = {
                    Uid = uid,
                    AssetCategory = instance:GetAttribute("AssetCategory")
                        or instance:GetAttribute("EggName")
                        or instance.Name,
                    AreaId = instance:GetAttribute("Area") or instance:GetAttribute("AreaId"),
                    Instance = instance,
                    State = "ClientObject",
                }
                seen[tostring(uid)] = true
            end
        end
    end

    local root = self:GetRoot()
    table.sort(records, function(left, right)
        local leftPosition = self:GetEggPosition(left)
        local rightPosition = self:GetEggPosition(right)
        local leftDistance = root and leftPosition and (root.Position - leftPosition).Magnitude or math.huge
        local rightDistance = root and rightPosition and (root.Position - rightPosition).Magnitude or math.huge
        return leftDistance < rightDistance
    end)

    return records
end

function Scanner:GetPlot()
    if type(self.PlotCmds) == "table" then
        for _, methodName in ipairs({"ResolvePlot", "GetPlotData"}) do
            local method = self.PlotCmds[methodName]
            if type(method) == "function" then
                local ok, data = pcall(method)
                if ok and type(data) == "table" and (data.PetArea or data.CenterPoint) then
                    return data
                end
            end
        end
    end

    local plots = self.Workspace:FindFirstChild("Plots")
    if not plots then return nil end
    for _, plot in ipairs(plots:GetChildren()) do
        local owner = plot:GetAttribute("Owner")
            or plot:GetAttribute("OwnerUserId")
            or plot:GetAttribute("OwnerId")
        if tostring(owner) == tostring(self.Player.UserId) or tostring(owner) == self.Player.Name then
            return {
                PlotFolder = plot,
                PetArea = plot:FindFirstChild("PetArea", true),
                CenterPoint = plot:FindFirstChild("CenterPoint", true),
            }
        end
    end
    return nil
end

function Scanner:GetAreas()
    local objects = self.Workspace:FindFirstChild("__OBJECTS")
    local areas = objects and objects:FindFirstChild("Areas")
    local guardAreas = areas and areas:FindFirstChild("GuardAreas")
    return guardAreas and guardAreas:GetChildren() or {}
end

function Scanner:Diagnostics()
    local eggs = self:GetEggs()
    local plot = self:GetPlot()
    local areas = self:GetAreas()
    return string.format(
        "Яйца: %d  •  Участок: %s  •  Биомы: %d",
        #eggs,
        plot and "найден" or "не найден",
        #areas
    )
end

return Scanner
]====]

M["modules/network.lua"] = [====[
-- MilfaCheatHUB • Networking diagnostics
-- This module discovers known remotes and reports their classes.

local Network = {}
Network.__index = Network

function Network.new(config)
    local self = setmetatable({}, Network)
    self.Config = config
    self.RS = game:GetService("ReplicatedStorage")
    self.CachedFolder = nil
    return self
end

function Network:GetFolder()
    if self.CachedFolder and self.CachedFolder.Parent then return self.CachedFolder end
    local packages = self.RS:FindFirstChild("Packages")
    self.CachedFolder = packages and packages:FindFirstChild("Networking")
    return self.CachedFolder
end

function Network:Find(endpoint)
    local folder = self:GetFolder()
    return folder and folder:FindFirstChild(endpoint) or nil
end

function Network:Scan()
    local rows = {}
    for _, endpoint in ipairs(self.Config.KnownEndpoints) do
        local instance = self:Find(endpoint)
        rows[#rows + 1] = {
            Endpoint = endpoint,
            Found = instance ~= nil,
            Class = instance and instance.ClassName or "missing",
            Instance = instance,
        }
    end
    return rows
end

function Network:Summary()
    local found, total = 0, 0
    for _, row in ipairs(self:Scan()) do
        total = total + 1
        if row.Found then found = found + 1 end
    end
    return string.format("Networking: %d/%d известных объектов найдено", found, total)
end

function Network:DetailedSummary(limit)
    local lines = {}
    for _, row in ipairs(self:Scan()) do
        if row.Found then
            lines[#lines + 1] = "✓ " .. row.Endpoint .. " [" .. row.Class .. "]"
        end
        if limit and #lines >= limit then break end
    end
    return #lines > 0 and table.concat(lines, "\n") or "Известные Remotes не найдены"
end

return Network
]====]

M["modules/rarity.lua"] = [====[
-- MilfaCheatHUB • Steal An Egg
-- Rarity engine: detection, ranking and colors (wiki + community tiers).

local Rarity = {}
Rarity.__index = Rarity

-- Detection order matters: first match wins (Uncommon before Common, etc.)
Rarity.List = {
    { Id = "Divine",    Rank = 100, Color = Color3.fromRGB(255, 228, 92),  Words = {"divine", "transcendent", "superior", "archangel", "world burner", "aetheron"} },
    { Id = "Eternal",   Rank = 95,  Color = Color3.fromRGB(41, 217, 255),  Words = {"eternal", "limited"} },
    { Id = "Secret",    Rank = 90,  Color = Color3.fromRGB(30, 26, 44),    Words = {"secret", "exotic"} },
    { Id = "Cosmic",    Rank = 80,  Color = Color3.fromRGB(99, 102, 255),  Words = {"cosmic", "galaxy", "exclusive", "admin"} },
    { Id = "Titan",     Rank = 78,  Color = Color3.fromRGB(255, 110, 64),  Words = {"titan", "colossal", "giant", "huge"} },
    { Id = "LightDark", Rank = 77,  Color = Color3.fromRGB(120, 160, 255), Words = {"light & dark", "lightdark", "light and dark"} },
    { Id = "Godly",     Rank = 75,  Color = Color3.fromRGB(255, 92, 60),   Words = {"godly"} },
    { Id = "Brainrot",  Rank = 72,  Color = Color3.fromRGB(168, 85, 247),  Words = {"brainrot", "tung", "sahur", "bananita", "tralaledon", "patapim", "trulimero"} },
    { Id = "Monster",   Rank = 70,  Color = Color3.fromRGB(124, 200, 74),  Words = {"monster", "krakenoid", "dreadscale", "crocodon", "crawler", "froggo"} },
    { Id = "Mecha",     Rank = 68,  Color = Color3.fromRGB(152, 162, 178), Words = {"mecha", "robot"} },
    { Id = "Mythic",    Rank = 65,  Color = Color3.fromRGB(255, 61, 129),  Words = {"mythic", "mythical", "myth", "prismatic", "rainbow", "brainrot god"} },
    { Id = "Legendary", Rank = 50,  Color = Color3.fromRGB(255, 170, 40),  Words = {"legendary", "legend"} },
    { Id = "Epic",      Rank = 40,  Color = Color3.fromRGB(176, 90, 250),  Words = {"epic"} },
    { Id = "Rare",      Rank = 30,  Color = Color3.fromRGB(64, 140, 255),  Words = {"rare", "superrare", "super rare", "celestial"} },
    { Id = "Uncommon",  Rank = 20,  Color = Color3.fromRGB(96, 202, 92),   Words = {"uncommon"} },
    { Id = "Common",    Rank = 10,  Color = Color3.fromRGB(178, 178, 178), Words = {"common", "basic"} },
    { Id = "Unknown",   Rank = 5,   Color = Color3.fromRGB(145, 138, 158), Words = {} },
}

local ById = {}
for _, entry in ipairs(Rarity.List) do
    ById[entry.Id] = entry
end

-- Fallback mapping for numeric rarity tiers (1..N)
Rarity.Tiers = {"Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic", "Godly", "Cosmic", "Secret", "Eternal", "Divine"}
Rarity._CategoryCache = {}

-- Lazy catalog of the game: RS.Data.Assets.Directory[category].Rarity
local Catalog = nil
local function loadCatalog()
    if Catalog ~= nil then return Catalog end
    local RS = game:GetService("ReplicatedStorage")
    local candidates = {}
    local data = RS:FindFirstChild("Data")
    if data then
        candidates[#candidates + 1] = data:FindFirstChild("Assets")
        candidates[#candidates + 1] = data
    end
    local shared = RS:FindFirstChild("Shared")
    if shared then
        candidates[#candidates + 1] = shared:FindFirstChild("Assets")
        local util = shared:FindFirstChild("Util")
        if util then candidates[#candidates + 1] = util:FindFirstChild("Assets") end
    end
    for _, instance in ipairs(candidates) do
        if instance and instance:IsA("ModuleScript") then
            local ok, module = pcall(require, instance)
            if ok and type(module) == "table" then
                if type(module.Directory) == "table" then
                    Catalog = module.Directory
                    return Catalog
                end
                local count = 0
                for key, value in pairs(module) do
                    if type(value) == "table" then count = count + 1 end
                end
                if count > 5 then
                    Catalog = module
                    return Catalog
                end
            end
        end
    end
    Catalog = false
    return Catalog
end

-- Resolve a rarity for an asset category via the in-game catalog (cached).
function Rarity.FromCategory(category)
    if type(category) ~= "string" or category == "" then return nil end
    local cache = Rarity._CategoryCache
    local cached = cache[category]
    if cached ~= nil then
        return cached or nil
    end
    local result = nil
    local directory = loadCatalog()
    if directory then
        local entry = directory[category]
        if type(entry) == "table" then
            local rarity = entry.Rarity
            if type(rarity) == "table" then
                result = Rarity.Detect(tostring(rarity._id or rarity.DisplayName or rarity.Name or ""))
            elseif type(rarity) == "string" then
                result = Rarity.Detect(rarity)
            elseif type(rarity) == "number" then
                result = Rarity.Tiers[math.floor(rarity)]
            end
            if not result then
                result = Rarity.Detect(tostring(entry.DisplayName or entry.Name or ""))
            end
        end
    end
    cache[category] = result or false
    return result
end

-- Resolve a rarity straight from an egg/pet instance (attributes or Data values).
function Rarity.FromInstance(instance)
    if not instance or not instance.Parent then return nil end
    local ok, attr = pcall(function()
        return instance:GetAttribute("Rarity")
            or instance:GetAttribute("RarityName")
            or instance:GetAttribute("RarityTier")
    end)
    if ok and type(attr) == "string" and attr ~= "" then
        return Rarity.Detect(attr)
    end
    if ok and type(attr) == "number" then
        return Rarity.Tiers[math.floor(attr)]
    end
    local data = instance:FindFirstChild("Data")
    if data then
        local rarityValue = data:FindFirstChild("Rarity")
        if rarityValue and rarityValue:IsA("ValueBase") then
            local valueOk, value = pcall(function() return rarityValue.Value end)
            if valueOk then
                if type(value) == "string" then return Rarity.Detect(value) end
                if type(value) == "number" then return Rarity.Tiers[math.floor(value)] end
            end
        end
    end
    return nil
end

function Rarity.ById(id)
    return ById[tostring(id)] or ById.Unknown
end

function Rarity.Rank(id)
    return Rarity.ById(id).Rank
end

function Rarity.Color(id)
    return Rarity.ById(id).Color
end

function Rarity.Ids()
    local out = {}
    for _, entry in ipairs(Rarity.List) do
        out[#out + 1] = entry.Id
    end
    return out
end

function Rarity.ValueIds()
    -- High-tier ids used by "keep" defaults (everything above Rare)
    return {"Legendary", "Mythic", "Giant", "Godly", "Brainrot", "Monster", "Mecha", "Cosmic", "Secret", "Eternal", "Divine"}
end

function Rarity.Detect(text)
    if type(text) ~= "string" or text == "" then return nil end
    local lowered = " " .. string.lower(text) .. " "
    for _, entry in ipairs(Rarity.List) do
        for _, word in ipairs(entry.Words) do
            if string.find(lowered, word, 1, true) then
                return entry.Id
            end
        end
    end
    return nil
end

function Rarity.FromRecord(record)
    if type(record) ~= "table" then return "Unknown" end

    local direct = record.Rarity or record.RarityTier or record.RarityName
    if type(direct) == "string" and direct ~= "" then
        return Rarity.Detect(direct)
            or Rarity.FromCategory(tostring(record.AssetCategory or ""))
            or Rarity.Detect(tostring(record.AssetCategory or ""))
            or "Unknown"
    end
    if type(direct) == "number" then
        local index = math.floor(direct)
        return Rarity.Tiers[index] or "Unknown"
    end

    local fromCategory = Rarity.FromCategory(tostring(record.AssetCategory or record.Category or ""))
    if fromCategory then return fromCategory end

    local candidates = {record.AssetCategory, record.EggName, record.DisplayName, record.Name, record.Category}
    for _, value in ipairs(candidates) do
        local detected = Rarity.Detect(tostring(value))
        if detected then return detected end
    end
    return "Unknown"
end

return Rarity
]====]

M["modules/positions.lua"] = [====[
-- MilfaCheatHUB • position resolver
-- Static values are diagnostics only; live objects are preferred.

local Positions = {}
Positions.__index = Positions

function Positions.new(config, scanner)
    local self = setmetatable({}, Positions)
    self.Config = config
    self.Scanner = scanner
    self.Static = {
        Anchor = Vector3.new(536.4492797851562, 70.28306579589844, -365.0294189453125),
        GateIn = Vector3.new(578, 70.3, -365.03),
        SafeZone = Vector3.new(545, 68, -364),
    }
    self.AreaX = {
        Forest = 602,
        Lake = 746,
        Desert = 785,
        Jungle = 936,
        Snow = 1076,
        Volcano = 1202,
        ["Abyss Ocean"] = 1370,
        Prehistoric = 1580,
        Cosmic = 1772,
        ["Cherry Blossom"] = 2479,
    }
    return self
end

local function instancePosition(instance)
    if not instance then return nil end
    if instance:IsA("BasePart") then return instance.Position end
    if instance:IsA("Model") then return instance:GetPivot().Position end
    local part = instance:FindFirstChildWhichIsA("BasePart", true)
    return part and part.Position or nil
end

function Positions:GetHome()
    local plot = self.Scanner:GetPlot()
    local petArea = plot and plot.PetArea
    local position = instancePosition(petArea)
    if position then return position, "Plot.PetArea" end

    local spawn = workspace:FindFirstChildWhichIsA("SpawnLocation", true)
    if spawn then return spawn.Position, spawn:GetFullName() end
    return nil, "missing"
end

function Positions:GetSeparationLine()
    local objects = workspace:FindFirstChild("__OBJECTS")
    local areas = objects and objects:FindFirstChild("Areas")
    local line = areas and areas:FindFirstChild("SeparationLine")
    return instancePosition(line), line
end

function Positions:GetDynamicPoints()
    local output = {}
    local home, source = self:GetHome()
    if home then output[#output + 1] = {Name = "Home", Position = home, Source = source} end

    local linePosition, line = self:GetSeparationLine()
    if linePosition then
        output[#output + 1] = {
            Name = "SeparationLine",
            Position = linePosition,
            Source = line:GetFullName(),
        }
    end

    for _, area in ipairs(self.Scanner:GetAreas()) do
        local position = instancePosition(area)
        if position then
            output[#output + 1] = {
                Name = area.Name,
                Position = position,
                Source = area:GetFullName(),
            }
        end
    end
    return output
end

function Positions:Summary()
    local points = self:GetDynamicPoints()
    local home = self:GetHome()
    return string.format(
        "Динамические точки: %d  •  База: %s",
        #points,
        home and "найдена" or "не найдена"
    )
end

function Positions:ListText(maxLines)
    local lines = {}
    for _, point in ipairs(self:GetDynamicPoints()) do
        local p = point.Position
        lines[#lines + 1] = string.format("%s: %.1f, %.1f, %.1f", point.Name, p.X, p.Y, p.Z)
        if maxLines and #lines >= maxLines then break end
    end
    return #lines > 0 and table.concat(lines, "\n") or "Динамические точки не найдены"
end

return Positions
]====]

M["modules/esp.lua"] = [====[
-- MilfaCheatHUB • client-side Egg ESP with rarity colors (stealth v0.4)

local ESP = {}
ESP.__index = ESP

local function randomName(stealth)
    if stealth and stealth.RandomName then return stealth.RandomName(14) end
    return "ESP_" .. tostring(math.random(100000, 999999))
end

local function safeParent(folder, stealth)
    -- Preferred: shared hidden container (CoreGui/gethui) — invisible to game scanners
    if stealth and stealth.GetContainer then
        local ok, container = pcall(stealth.GetContainer, stealth)
        if ok and container then
            local attached = pcall(function() folder.Parent = container end)
            if attached and folder.Parent == container then return true end
        end
    end

    local targets = {}
    if gethui then
        local ok, value = pcall(gethui)
        if ok and value then targets[#targets + 1] = value end
    end
    targets[#targets + 1] = game:GetService("CoreGui")
    local player = game:GetService("Players").LocalPlayer
    if player then targets[#targets + 1] = player:FindFirstChildOfClass("PlayerGui") end

    for _, target in ipairs(targets) do
        if target then
            local ok = pcall(function() folder.Parent = target end)
            if ok and folder.Parent then return true end
        end
    end
    return false
end

function ESP.new(config, rarity, stealth)
    local self = setmetatable({}, ESP)
    self.Config = config
    self.Rarity = rarity
    self.Stealth = stealth
    self.Enabled = false
    self.Objects = {}
    self.Folder = Instance.new("Folder")
    self.Folder.Name = randomName(stealth)
    safeParent(self.Folder, stealth)
    return self
end

function ESP:Clear()
    for _, object in ipairs(self.Objects) do
        pcall(function() object:Destroy() end)
    end
    self.Objects = {}
end

function ESP:SetEnabled(value)
    self.Enabled = value == true
    if not self.Enabled then self:Clear() end
end

local function findAdornee(instance)
    if not instance then return nil end
    if instance:IsA("BasePart") then return instance end
    return instance:FindFirstChildWhichIsA("BasePart", true)
end

function ESP:Refresh(records, scanner)
    if not self.Enabled or not self.Folder or not self.Folder.Parent then return end
    self:Clear()

    local settings = self.Config.Settings
    local colors = self.Config.Colors
    local root = scanner:GetRoot()
    local maxDistance = settings.EspMaxDistance or 1500

    for _, record in ipairs(records) do
        if not self.Enabled then break end
        local instance = scanner:GetEggInstance(record) or record.Instance
        local position = scanner:GetEggPosition(record) or record.Position
        local adornee = findAdornee(instance)

        if instance and adornee and position then
            local distance = root and math.floor((root.Position - position).Magnitude) or 0
            if distance <= maxDistance then
                local rarityId = record.Rarity or self.Rarity.FromRecord(record)
                local useRarityColor = settings.ShowRarity ~= false
                local fillColor = useRarityColor and self.Rarity.Color(rarityId) or colors.ESP
                local outlineColor = useRarityColor and self.Rarity.Color(rarityId) or colors.Accent

                local highlight = Instance.new("Highlight")
                highlight.Name = randomName(self.Stealth)
                highlight.Adornee = instance
                highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                highlight.FillColor = fillColor
                highlight.FillTransparency = 0.72
                highlight.OutlineColor = outlineColor
                highlight.OutlineTransparency = 0.05
                highlight.Parent = self.Folder
                self.Objects[#self.Objects + 1] = highlight

                local billboard = Instance.new("BillboardGui")
                billboard.Name = randomName(self.Stealth)
                billboard.Adornee = adornee
                billboard.Size = UDim2.fromOffset(210, 52)
                billboard.StudsOffset = Vector3.new(0, 3.4, 0)
                billboard.AlwaysOnTop = true
                billboard.MaxDistance = maxDistance
                billboard.Parent = self.Folder

                local name = record.Name or record.AssetCategory or record.DisplayName or record.Uid or "Egg"
                local area = record.AreaId and (" • " .. tostring(record.AreaId)) or ""
                local lines = tostring(name) .. area
                if settings.ShowRarity then
                    lines = lines .. "\n[" .. tostring(rarityId) .. "]"
                end
                if settings.ShowDistance then
                    lines = lines .. " " .. distance .. " studs"
                end

                local label = Instance.new("TextLabel")
                label.Size = UDim2.fromScale(1, 1)
                label.BackgroundTransparency = 1
                label.Text = lines
                label.RichText = false
                label.TextColor3 = useRarityColor and fillColor or colors.Text
                label.TextStrokeColor3 = colors.Background
                label.TextStrokeTransparency = 0.16
                label.Font = Enum.Font.Code
                label.TextSize = 12
                label.Parent = billboard
                self.Objects[#self.Objects + 1] = billboard
            end
        end
    end
end

function ESP:Destroy()
    self.Enabled = false
    self:Clear()
    if self.Folder then
        self.Folder:Destroy()
        self.Folder = nil
    end
end

return ESP
]====]

M["modules/eggs.lua"] = [====[
-- MilfaCheatHUB • egg engine
-- Rich egg records: rarity, prompts, distance, filters and sell remote discovery.

local Eggs = {}
Eggs.__index = Eggs

function Eggs.new(config, scanner, network, rarity)
    local self = setmetatable({}, Eggs)
    self.Config = config
    self.Scanner = scanner
    self.Network = network
    self.Rarity = rarity
    self.Workspace = game:GetService("Workspace")
    self.Players = game:GetService("Players")
    self.Player = self.Players.LocalPlayer
    return self
end

function Eggs:GetRoot()
    local character = self.Player.Character
    return character and character:FindFirstChild("HumanoidRootPart")
end

local function partOf(instance)
    if not instance then return nil end
    if instance:IsA("BasePart") then return instance end
    return instance:FindFirstChild("Hitbox")
        or instance.PrimaryPart
        or instance:FindFirstChildWhichIsA("BasePart", true)
end

function Eggs:GetEggFolders()
    local folders = {}
    for _, name in ipairs({"AreaEggSlotsClient", "Eggs", "SpawnedEggs"}) do
        local folder = self.Workspace:FindFirstChild(name)
        if folder then folders[#folders + 1] = folder end
    end
    return folders
end

-- Collect every visible egg on the map with rich metadata.
function Eggs:Scan()
    local records, seen = {}, {}
    local root = self:GetRoot()

    -- 1) Server snapshot through client state (best data)
    local snapshot = self.Scanner:ReadEggSnapshot()
    if type(snapshot) == "table" then
        for key, record in pairs(snapshot) do
            if type(record) == "table" then
                local uid = record.Uid or record.UID or record.Id or (type(key) == "string" and key)
                if uid and not seen[tostring(uid)] then
                    seen[tostring(uid)] = true
                    records[#records + 1] = {
                        Uid = tostring(uid),
                        Name = tostring(record.AssetCategory or record.EggName or record.DisplayName or uid),
                        Instance = self.Scanner:GetEggInstance(record),
                        State = record.State or "Snapshot",
                        AssetCategory = record.AssetCategory,
                        AreaId = record.AreaId,
                        NestId = record.NestId,
                        Mutations = record.Mutations,
                    }
                end
            end
        end
    end

    -- 2) Workspace folders
    for _, folder in ipairs(self:GetEggFolders()) do
        for _, instance in ipairs(folder:GetChildren()) do
            local lowered = string.lower(instance.Name)
            if not string.find(lowered, "nest", 1, true) and not seen[tostring(instance.Name)] then
                seen[tostring(instance.Name)] = true
                records[#records + 1] = {
                    Uid = tostring(instance:GetAttribute("UID") or instance:GetAttribute("Uid") or instance.Name),
                    Name = instance.Name,
                    Instance = instance,
                    State = "ClientObject",
                }
            end
        end
    end

    -- 3) Native steal prompts (SmartPromptPart)
    for _, instance in ipairs(self.Workspace:GetChildren()) do
        if instance.Name == "SmartPromptPart" then
            local prompt = instance:FindFirstChildWhichIsA("ProximityPrompt")
            if prompt then
                local key = "prompt_" .. tostring(instance.Position)
                if not seen[key] then
                    seen[key] = true
                    records[#records + 1] = {
                        Uid = key,
                        Name = tostring(prompt.ObjectText ~= "" and prompt.ObjectText or "Egg"),
                        Instance = instance,
                        Prompt = prompt,
                        State = "Prompt",
                    }
                end
            end
        end
    end

    -- Enrich records
    for _, record in ipairs(records) do
        record.Rarity = self.Rarity.FromRecord(record)
        if record.Rarity == "Unknown" then
            local fromInstance = self.Rarity.FromInstance(record.Instance)
            if fromInstance then record.Rarity = fromInstance end
        end
        record.Rank = self.Rarity.Rank(record.Rarity)
        local part = partOf(record.Instance)
        record.Part = part
        record.Position = part and part.Position or nil
        record.Distance = (root and record.Position) and math.floor((root.Position - record.Position).Magnitude) or math.huge
        record.Prompt = record.Prompt or (record.Instance and record.Instance:FindFirstChildWhichIsA("ProximityPrompt", true))
    end

    return records
end

-- First-area eggs REQUIRE FirstAreaSlotKey (e.g. "Forest:Slot_004").
-- RSpy: AskFieldEggCarry({FirstAreaSlotKey = "Forest:Slot_004", Uid = "FirstAreaEgg_..._Forest:Slot_004"})
function Eggs:ParseFirstAreaSlotKey(uid, record)
    local text = tostring(uid or "")
    local key = string.match(text, "^FirstAreaEgg_%d+_%d+_(.+)$")
    if key and key ~= "" then return key end

    if type(record) == "table" then
        local area = record.AreaId or record.Area
        local nest = record.NestId or record.Nest or record.SlotKey
        if type(nest) == "string" and string.find(nest, ":", 1, true) then
            return nest
        end
        if type(area) == "string" and type(nest) == "string" and string.find(nest, "Slot_", 1, true) then
            return area .. ":" .. nest
        end
    end
    return nil
end

-- Local save state (RS.Shared.Save): Inventory (pets) and EggInventory (eggs).
function Eggs:GetSave()
    local scanner = self.Scanner
    if scanner and type(scanner.GetSave) == "function" then
        return scanner:GetSave()
    end
    return nil
end

function Eggs:GetEggInventory()
    local save = self:GetSave()
    if type(save) == "table" and type(save.EggInventory) == "table" then
        return save.EggInventory
    end
    return nil
end

function Eggs:GetPetInventory()
    local save = self:GetSave()
    if type(save) == "table" and type(save.Inventory) == "table" then
        return save.Inventory
    end
    return nil
end

function Eggs:Filter(records, options)
    options = options or {}
    local filterList = options.Rarities
    local maxDistance = options.MaxDistance or 0
    local query = options.Query and string.lower(options.Query) or nil

    local allowed = nil
    if type(filterList) == "table" and #filterList > 0 then
        allowed = {}
        for _, id in ipairs(filterList) do allowed[tostring(id)] = true end
    end

    local out = {}
    for _, record in ipairs(records) do
        local ok = true
        if allowed and not allowed[record.Rarity] then ok = false end
        if ok and maxDistance > 0 and record.Distance > maxDistance then ok = false end
        if ok and query and query ~= "" then
            local nameLower = string.lower(record.Name)
            if not string.find(nameLower, query, 1, true) then ok = false end
        end
        if ok then out[#out + 1] = record end
    end
    return out
end

function Eggs:Sort(records, mode)
    local root = self:GetRoot()
    table.sort(records, function(left, right)
        if mode == "distance" then
            return left.Distance < right.Distance
        end
        if left.Rank ~= right.Rank then return left.Rank > right.Rank end
        return left.Distance < right.Distance
    end)
    return records
end

-- Held egg: Tool/Model with "egg" in the name inside character or backpack.
function Eggs:GetHeldEgg()
    local character = self.Player.Character
    local containers = {character, self.Player:FindFirstChild("Backpack")}
    for _, container in ipairs(containers) do
        if container then
            for _, item in ipairs(container:GetChildren()) do
                if (item:IsA("Tool") or item:IsA("Model")) and string.find(string.lower(item.Name), "egg", 1, true) then
                    return item
                end
            end
        end
    end
    return nil
end

function Eggs:GetHeldEggUid()
    local held = self:GetHeldEgg()
    if not held then return nil, nil end
    return held:GetAttribute("UID") or held:GetAttribute("Uid") or held.Name, held
end

-- Sell remote: RSpy/research-confirmed RE/PetSatchel/SellPet first, then discovery.
function Eggs:FindSellRemotes()
    local found, seen = {}, {}
    local function push(instance)
        if instance and not seen[instance] then
            seen[instance] = true
            found[#found + 1] = instance
        end
    end

    for _, name in ipairs(self.Config.SellCandidates or {}) do
        push(self.Network:Find(name))
    end

    local folder = self.Network:GetFolder()
    if folder then
        for _, instance in ipairs(folder:GetDescendants()) do
            if instance:IsA("RemoteFunction") or instance:IsA("RemoteEvent") then
                local lowered = string.lower(instance.Name)
                if string.find(lowered, "sell", 1, true) or string.find(lowered, "satchel", 1, true) or string.find(lowered, "sale", 1, true) then
                    push(instance)
                end
            end
        end
    end
    return found
end

-- Pets roster via client modules (best effort) for rarity-filtered selling.
function Eggs:GetPetRoster()
    local RS = game:GetService("ReplicatedStorage")
    local modules = {RS:FindFirstChild("Client"), RS:FindFirstChild("Library")}
    for _, root in ipairs(modules) do
        if root then
            for _, name in ipairs({"PenRosterCmds", "PetCmds", "RosterCmds"}) do
                local folder = root:FindFirstChild(name) or (root:FindFirstChild("Client") and root.Client:FindFirstChild(name))
                if folder then
                    local ok, module = pcall(require, folder)
                    if ok and type(module) == "table" then
                        for _, method in ipairs({"GetRoster", "GetPets", "ReadRoster", "GetPenRoster", "GetRosterData"}) do
                            local fn = module[method]
                            if type(fn) == "function" then
                                local callOk, data = pcall(fn)
                                if callOk and type(data) == "table" then
                                    return data, name .. "." .. method
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    return nil, "not found"
end

return Eggs
]====]

M["modules/automation.lua"] = [====[
-- MilfaCheatHUB • automation engine v0.4 (stealth)
-- Auto steal / place / hatch / sell / collect / treadmill / upgrades / pets / traps / server hop.
-- Remote shapes are RSpy-confirmed (see LIST.md). All teleports glide, all delays humanized.

local Automation = {}
Automation.__index = Automation
local AutomationRef = nil
AutomationRef = Automation

function Automation.new(config, eggs, network, positions, scanner, rarity, stealth)
    local self = setmetatable({}, Automation)
    self.Config = config
    self.Eggs = eggs
    self.Network = network
    self.Positions = positions
    self.Scanner = scanner
    self.Rarity = rarity
    self.Stealth = stealth
    self.Running = false
    self.EmptyRuns = 0
    self.LastHop = 0
    self.TreadmillName = nil
    self.Status = {
        Steal = "выключено",
        Sell = "выключено",
        Hatch = "выключено",
        Collect = "выключено",
        Hop = "выключено",
        Treadmill = "выключено",
        Upgrades = "выключено",
        Pets = "выключено",
        Traps = "выключено",
    }
    return self
end

local function getRoot()
    local player = game:GetService("Players").LocalPlayer
    local character = player.Character
    return character and character:FindFirstChild("HumanoidRootPart"), character
end

-- BAC-safe teleport: glide like fast walking instead of a 300-stud CFrame jump.
-- Yields while gliding so remote calls fire only when we actually arrived.
local function teleport(position, height, glideSpeed)
    local root = getRoot()
    if not root or not position then return false end
    local stealth = AutomationRef and AutomationRef.Stealth
    if stealth and stealth.GlideTo and AutomationRef.Config.Settings.SafeTeleport then
        stealth.SafeTeleport = true
        stealth.GlideSpeed = glideSpeed or AutomationRef.Config.Settings.GlideSpeed or 48
        pcall(stealth.GlideTo, stealth, position, {Height = height or 2.5})
        return true
    end
    root.CFrame = CFrame.new(position + Vector3.new(0, height or 2.5, 0))
    return true
end

local function pause(base)
    local stealth = AutomationRef and AutomationRef.Stealth
    local value = base
    if AutomationRef and AutomationRef.Config.Settings.HumanizeDelays then
        if stealth and stealth.Jitter then
            value = stealth.Jitter(base)
        else
            value = base * (0.75 + math.random() * 0.6)
        end
    end
    if value and value > 0 then task.wait(value) end
end

local function firePrompt(prompt)
    if not prompt then return false end
    if fireproximityprompt then
        local ok = pcall(fireproximityprompt, prompt)
        if ok then return true end
    end
    if getconnections then
        local ok, connections = pcall(getconnections, prompt.Triggered)
        if ok and type(connections) == "table" then
            for _, connection in ipairs(connections) do
                pcall(function() connection:Fire() end)
            end
            return true
        end
    end
    return false
end

local function invoke(remote, ...)
    if not remote then return nil, "missing" end
    local args = {...}
    if remote:IsA("RemoteFunction") then
        local ok, result = pcall(function() return remote:InvokeServer(unpack(args)) end)
        if ok then return true, result end
        return nil, tostring(result)
    end
    local ok = pcall(function() remote:FireServer(unpack(args)) end)
    if ok then return true end
    return nil, "fire failed"
end

function Automation:IsRarityAllowed(id, list)
    if type(list) ~= "table" or #list == 0 then return true end
    for _, entry in ipairs(list) do
        if tostring(entry) == tostring(id) then return true end
    end
    return false
end

function Automation:IsBelowKeep(rank)
    local keep = self.Config.Settings.KeepRarities or {}
    local keepRanks = {}
    for _, id in ipairs(keep) do
        keepRanks[self.Rarity.Rank(id)] = true
    end
    -- Sell everything that is NOT in the keep list (by id, not rank compare)
    return keepRanks[rank] == nil
end

function Automation:PickTarget()
    local records = self.Eggs:Scan()
    local settings = self.Config.Settings
    local candidates = self.Eggs:Filter(records, {
        Rarities = settings.RarityFilter,
        MaxDistance = settings.StealRadius,
    })
    -- Skip eggs sitting in our own base area
    local home = self.Positions:GetHome()
    local ownBaseRadius = 55
    local best = nil
    for _, record in ipairs(candidates) do
        local inBase = home and record.Position and (record.Position - home).Magnitude < ownBaseRadius
        if not inBase and record.Position then
            if not best then
                best = record
            elseif settings.StealPriority == "distance" then
                if record.Distance < best.Distance then best = record end
            elseif record.Rank > best.Rank or (record.Rank == best.Rank and record.Distance < best.Distance) then
                best = record
            end
        end
    end
    return best
end

function Automation:StealOne(record)
    local settings = self.Config.Settings
    record = record or self:PickTarget()
    if not record or not record.Position then return false, "целей нет" end

    if settings.StealTeleport then
        teleport(record.Position)
        pause(0.2)
    end

    local networking = self.Network:GetFolder()
    local askCarry = networking and networking:FindFirstChild("RF/EggWorld/AskFieldEggCarry")
    -- RSpy: single table with BOTH Uid and FirstAreaSlotKey (mandatory for first areas)
    local carryArgs = {Uid = record.Uid}
    local slotKey = self.Eggs:ParseFirstAreaSlotKey(record.Uid, record)
    if slotKey then carryArgs.FirstAreaSlotKey = slotKey end
    local ok = invoke(askCarry, carryArgs)
    local promptOk = firePrompt(record.Prompt)

    -- Give the server a moment, then walk home and place.
    pause(0.35)
    local placed = false
    if settings.AutoReturn then
        local home = self.Positions:GetHome()
        if home then
            if settings.StealTeleport then
                teleport(home, 3)
                pause(0.3)
            end
            local uid = self.Eggs:GetHeldEggUid()
            if uid then
                local askPlace = networking and networking:FindFirstChild("RF/EggWorld/AskPlaceEgg")
                placed = invoke(askPlace, {Uid = tostring(uid), LocalCFrame = CFrame.new(0, -0.5, 0)})
            end
        end
    end
    local where = slotKey and (" (" .. tostring(slotKey) .. ")") or ""
    return ok or promptOk or placed, string.format("%s [%s]%s", record.Name, record.Rarity, where)
end

function Automation:DropHeld()
    local player = game:GetService("Players").LocalPlayer
    local pgui = player:FindFirstChild("PlayerGui")
    local dropGui = pgui and pgui:FindFirstChild("DropHeldEgg")
    local dropButton = dropGui and dropGui:FindFirstChild("Button", true)
    if dropButton then
        if firesignal then
            pcall(firesignal, dropButton.MouseButton1Click)
            pcall(firesignal, dropButton.Activated)
        end
        if getconnections then
            pcall(function()
                for _, connection in ipairs(getconnections(dropButton.MouseButton1Click)) do connection:Fire() end
                for _, connection in ipairs(getconnections(dropButton.Activated)) do connection:Fire() end
            end)
        end
        return true
    end

    local networking = self.Network:GetFolder()
    for _, name in ipairs({"RF/EggWorld/AskFieldEggDrop", "RE/EggWorld/AskFieldEggDrop"}) do
        local remote = networking and networking:FindFirstChild(name)
        if remote then
            local uid = self.Eggs:GetHeldEggUid()
            invoke(remote, {Uid = uid})
            return true
        end
    end
    return false
end

function Automation:PlaceHeldEggs()
    local networking = self.Network:GetFolder()
    local askPlace = networking and networking:FindFirstChild("RF/EggWorld/AskPlaceEgg")
    if not askPlace then return 0 end

    local player = game:GetService("Players").LocalPlayer
    local containers = {player.Character, player:FindFirstChild("Backpack")}
    local count = 0
    for _, container in ipairs(containers) do
        if container then
            for _, item in ipairs(container:GetChildren()) do
                if item:IsA("Tool") and item:GetAttribute("UID")
                    and (item:GetAttribute("ItemType") == "AssetEgg" or string.find(string.lower(item.Name), "egg", 1, true)) then
                    local ok = invoke(askPlace, {Uid = tostring(item:GetAttribute("UID")), LocalCFrame = CFrame.new(0, -0.5, 0)})
                    if ok then count = count + 1 end
                    pause(0.2)
                end
            end
        end
    end
    return count
end

function Automation:HatchReady()
    local player = game:GetService("Players").LocalPlayer
    local networking = self.Network:GetFolder()
    local askHatch = networking and networking:FindFirstChild("RF/EggWorld/AskHatch")
    local fired = 0
    local cap = math.max(1, self.Config.Settings.MaxHatchPerTick or 4)

    -- 1) Best source: placed eggs from save.EggInventory. RSpy: AskHatch("hex-uid") — plain string.
    local inv = self.Eggs:GetEggInventory()
    if askHatch and inv then
        for uid, entry in pairs(inv) do
            if fired >= cap then break end
            if type(entry) == "table" and entry.Placement ~= nil and not entry.Locked then
                local ok = invoke(askHatch, tostring(uid))
                if ok then fired = fired + 1; pause(0.2) end
            end
        end
    end

    -- 2) GUI fallback: GrowingEggs ready buttons
    local pgui = player:FindFirstChild("PlayerGui")
    local growing = pgui and pgui:FindFirstChild("GrowingEggs")
    if growing then
        for _, button in ipairs(growing:GetDescendants()) do
            if button:IsA("GuiButton") and button.Visible then
                if firesignal then
                    pcall(firesignal, button.MouseButton1Click)
                    pcall(firesignal, button.Activated)
                    fired = fired + 1
                end
                if getconnections then
                    pcall(function()
                        for _, connection in ipairs(getconnections(button.MouseButton1Click)) do connection:Fire(); fired = fired + 1 end
                        for _, connection in ipairs(getconnections(button.Activated)) do connection:Fire(); fired = fired + 1 end
                    end)
                end
            end
            if fired > cap then break end
        end
    end

    -- 3) Remote fallback for eggs placed near home (plain string uid)
    if askHatch and fired < cap then
        local home = self.Positions:GetHome()
        if home then
            for _, record in ipairs(self.Eggs:Scan()) do
                if record.Position and (record.Position - home).Magnitude < 60 and fired < cap then
                    local ok = invoke(askHatch, tostring(record.Uid))
                    if ok then fired = fired + 1; pause(0.2) end
                end
            end
        end
    end
    return fired
end

function Automation:CollectEarnings()
    local networking = self.Network:GetFolder()
    local collect = networking and networking:FindFirstChild("RF/AwayEarnings/AskCollect")
    if not collect then return false end
    -- RSpy: AskCollect({Kind = "Claim"})
    local ok = invoke(collect, {Kind = "Claim"})
    return ok == true
end

function Automation:WearTreadmill()
    local networking = self.Network:GetFolder()
    local wear = networking and networking:FindFirstChild("RF/Treadmill/AskWearStill")
    -- RSpy: AskWearStill() — no arguments
    if wear then invoke(wear) end

    local workspace = game:GetService("Workspace")
    local treadmill = workspace:FindFirstChild("Treadmills") or workspace:FindFirstChild("Gym")
    if treadmill then
        local prompt = treadmill:FindFirstChildWhichIsA("ProximityPrompt", true)
        firePrompt(prompt)
    end
    return true
end

function Automation:DoffTreadmill()
    local networking = self.Network:GetFolder()
    local doff = networking and networking:FindFirstChild("RF/Treadmill/AskDoff")
    if not doff then return false end
    local ok = invoke(doff)
    return ok == true
end

function Automation:FindTreadmillName()
    if self.TreadmillName then return self.TreadmillName end
    local workspace = game:GetService("Workspace")
    local roots = {
        workspace:FindFirstChild("Treadmills"),
        workspace:FindFirstChild("Gym"),
    }
    local objects = workspace:FindFirstChild("__OBJECTS")
    if objects then roots[#roots + 1] = objects end
    for _, root in ipairs(roots) do
        if root then
            for _, descendant in ipairs(root:GetDescendants()) do
                if descendant:IsA("Model") or descendant:IsA("BasePart") then
                    if string.find(descendant.Name, "Treadmill", 1, true)
                        or string.find(string.lower(descendant.Name), "treadmill", 1, true) then
                        self.TreadmillName = descendant.Name
                        return self.TreadmillName
                    end
                end
            end
        end
    end
    -- RSpy-captured default
    self.TreadmillName = "FlameTreadmill"
    return self.TreadmillName
end

function Automation:UpgradeTreadmill()
    local networking = self.Network:GetFolder()
    local raise = networking and networking:FindFirstChild("RF/Treadmill/AskTierRaise")
    if not raise then return false end
    -- RSpy: AskTierRaise("FlameTreadmill") — treadmill id string
    local ok = invoke(raise, self:FindTreadmillName())
    return ok == true
end

function Automation:UpgradeBase()
    local networking = self.Network:GetFolder()
    local raise = networking and networking:FindFirstChild("RE/Homestead/AskBaseTierRaise")
    if not raise then return false end
    -- RSpy: RE/Homestead/AskBaseTierRaise:FireServer() — no arguments
    local ok = pcall(function() raise:FireServer() end)
    return ok
end

function Automation:WearBestPets()
    local settings = self.Config.Settings
    local networking = self.Network:GetFolder()
    local inv = self.Eggs:GetPetInventory()
    if type(inv) ~= "table" then return false, "инвентарь не читается" end

    local wear = networking and networking:FindFirstChild("RF/PenRoster/AskWear")
    if not wear then return false, "PenRoster/AskWear не найден" end

    -- Rank every unlocked pet, wear the best ones into free slots
    local list = {}
    for uid, entry in pairs(inv) do
        if type(entry) == "table" and not entry.Locked and not entry.InFuse then
            local rarity = self.Rarity.Detect(tostring(entry.Rarity or ""))
                or self.Rarity.FromCategory(tostring(entry.AssetCategory or ""))
                or self.Rarity.FromRecord(entry)
            list[#list + 1] = {Uid = tostring(uid), Rank = self.Rarity.Rank(rarity)}
        end
    end
    table.sort(list, function(left, right) return left.Rank > right.Rank end)

    local trigger = networking and networking:FindFirstChild("RE/ToolTrigger/Trigger")
    local best = networking and networking:FindFirstChild("RF/Haul/FetchWearBestStatus")
    local slots = math.max(1, settings.PetSlots or 3)
    local worn = 0
    for index, item in ipairs(list) do
        if worn >= slots then break end
        -- RSpy flow: ToolTrigger/Trigger(Tool) then PenRoster/AskWear(uid), then FetchWearBestStatus
        if trigger then pcall(function() trigger:FireServer(Instance.new("Tool")) end) end
        local ok = invoke(wear, item.Uid)
        if ok then worn = worn + 1 end
        pause(0.25)
    end
    if best then pcall(function() best:InvokeServer() end) end
    return worn > 0, "надето: " .. worn
end

function Automation:NeutralizeTraps()
    local player = game:GetService("Players").LocalPlayer
    local debris = workspace:FindFirstChild("__DEBRIS")
    if not debris then return 0 end
    local me = tostring(player.UserId)
    local count = 0
    for _, trap in ipairs(debris:GetChildren()) do
        if trap.Name == "PlayerTrap" then
            local owner = trap:GetAttribute("Owner") or trap:GetAttribute("OwnerUserId")
            if owner ~= nil and tostring(owner) ~= me and tostring(owner) ~= player.Name then
                pcall(function()
                    if trap:IsA("BasePart") then
                        trap.CanTouch = false
                        trap.CanQuery = false
                    end
                    for _, part in ipairs(trap:GetDescendants()) do
                        if part:IsA("BasePart") then
                            part.CanTouch = false
                            part.CanQuery = false
                        end
                    end
                end)
                count = count + 1
            end
        end
    end
    return count
end

function Automation:SellOnce()
    local settings = self.Config.Settings
    local remotes = self.Eggs:FindSellRemotes()
    local soldEggs, soldPets = 0, 0
    local sell = remotes[1]
    if not sell then return 0, 0, 0 end

    local networking = self.Network:GetFolder()
    local wearTool = networking and networking:FindFirstChild("RF/EggWorld/AskWearTool")
    local perTick = math.max(1, settings.SellPerTick or 8)
    local sellPause = math.max(0.05, settings.SellPerDelay or 0.15)

    local function sellRemoteCall(...)
        if sell:IsA("RemoteEvent") then
            local ok = pcall(function(...) sell:FireServer(...) end, ...)
            if ok then return true end
            return false
        end
        return invoke(sell, ...) == true
    end

    -- 1) Eggs via save.EggInventory: wear tool, then SellPet({uid}) — RSpy-confirmed shapes
    if settings.AutoSellEggs then
        local inv = self.Eggs:GetEggInventory()
        if inv then
            for uid, entry in pairs(inv) do
                if soldEggs >= perTick then break end
                if type(entry) == "table" and not entry.Placement and not entry.Locked then
                    local rarity = self.Rarity.FromCategory(tostring(entry.AssetCategory or ""))
                        or self.Rarity.FromRecord(entry)
                    if not self:IsRarityAllowed(rarity, settings.KeepRarities) then
                        local ok = false
                        if wearTool then
                            invoke(wearTool, tostring(uid))
                            pause(0.12)
                        end
                        ok = sellRemoteCall({tostring(uid)}) or sellRemoteCall(tostring(uid))
                        if ok then soldEggs = soldEggs + 1 end
                        pause(sellPause)
                    end
                end
            end
        else
            -- Fallback: eggs placed near home (scan-based)
            local home = self.Positions:GetHome()
            for _, record in ipairs(self.Eggs:Scan()) do
                if soldEggs >= perTick then break end
                if record.Position and home and (record.Position - home).Magnitude < 70
                    and self:IsBelowKeep(self.Rarity.Rank(record.Rarity)) then
                    local ok = false
                    if wearTool then
                        invoke(wearTool, tostring(record.Uid))
                        pause(0.12)
                    end
                    ok = sellRemoteCall({tostring(record.Uid)}) or sellRemoteCall(tostring(record.Uid))
                    if ok then soldEggs = soldEggs + 1 end
                    pause(sellPause)
                end
            end
        end
    end

    -- 2) Pets via save.Inventory: SellPet(uid) — RSpy-confirmed shape
    if settings.AutoSellPets then
        local inv = self.Eggs:GetPetInventory()
        if inv then
            for uid, entry in pairs(inv) do
                if soldPets >= perTick then break end
                if type(entry) == "table" and not entry.Locked and not entry.IsFavorite and not entry.InFuse then
                    local rarity = self.Rarity.Detect(tostring(entry.Rarity or ""))
                        or self.Rarity.FromCategory(tostring(entry.AssetCategory or ""))
                        or self.Rarity.FromRecord(entry)
                    if not self:IsRarityAllowed(rarity, settings.KeepRarities) then
                        local ok = sellRemoteCall(tostring(uid)) or sellRemoteCall({tostring(uid)})
                        if ok then soldPets = soldPets + 1 end
                        pause(sellPause)
                    end
                end
            end
        end
    end
    return soldEggs, soldPets, #remotes
end

function Automation:ServerHop()
    local TeleportService = game:GetService("TeleportService")
    local HttpService = game:GetService("HttpService")
    local player = game:GetService("Players").LocalPlayer
    local requestFn = request or http_request or (syn and syn.request)
    pcall(function()
        local url = "https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&limit=100"
        if requestFn then
            local response = requestFn({Url = url, Method = "GET"})
            if response and response.Body then
                local data = HttpService:JSONDecode(response.Body)
                for _, server in ipairs(data.data or {}) do
                    if server.playing < server.maxPlayers and server.id ~= game.JobId then
                        TeleportService:TeleportToPlaceInstance(game.PlaceId, server.id, player)
                        return
                    end
                end
            end
        end
        TeleportService:Teleport(game.PlaceId, player)
    end)
end

function Automation:FeedMonster()
    local root = getRoot()
    if not root then return false end
    local networking = self.Network:GetFolder()
    local eggsFolder = self.Eggs:GetEggFolders()[1]
    local target = nil
    if eggsFolder then
        for _, model in ipairs(eggsFolder:GetChildren()) do
            if string.find(string.lower(model.Name), "parasite", 1, true) then
                target = model
                break
            end
        end
    end
    if not target then return false end
    local part = target:IsA("BasePart") and target or target:FindFirstChildWhichIsA("BasePart", true)
    if part then
        teleport(part.Position)
        pause(0.3)
        local feed = networking and networking:FindFirstChild("RF/MonsterParasite/AskFeed")
        invoke(feed)
        return true
    end
    return false
end

function Automation:Start(alive)
    if self.Running then return end
    self.Running = true
    local settings = self.Config.Settings
    local lastSell = 0
    local lastCollect = 0
    local lastTreadmill = 0
    local lastPlace = 0
    local lastHatch = 0
    local lastDoff = 0
    local lastTreadmillUpgrade = 0
    local lastBaseUpgrade = 0
    local lastPets = 0
    local lastTraps = 0

    task.spawn(function()
        while self.Running and alive() do
            local now = os.clock()
            local ok, err = pcall(function()
                -- Auto steal loop
                if settings.AutoSteal then
                    local held = self.Eggs:GetHeldEgg()
                    if settings.AutoDrop and held then
                        self:DropHeld()
                        self.Status.Steal = "сброшено из рук"
                    elseif not held then
                        local done, info = self:StealOne()
                        self.EmptyRuns = done and 0 or self.EmptyRuns + 1
                        self.Status.Steal = done and ("украдено: " .. tostring(info)) or ("цели нет (" .. tostring(info) .. ")")
                        if settings.AutoServerHop and self.EmptyRuns >= (settings.HopEmptyRuns or 12) and now - self.LastHop > 30 then
                            self.LastHop = now
                            self.Status.Hop = "переключаемся..."
                            self:ServerHop()
                        end
                    else
                        self.Status.Steal = "яйцо в руках"
                    end
                elseif settings.AutoServerHop then
                    self.Status.Hop = "включён (требует автокражу)"
                end

                -- Auto place
                if settings.AutoPlace and now - lastPlace > 1.5 then
                    lastPlace = now
                    local count = self:PlaceHeldEggs()
                    if count > 0 then self.Status.Steal = "размещено: " .. count end
                end

                -- Auto hatch
                if settings.AutoHatch and now - lastHatch > 3 then
                    lastHatch = now
                    local count = self:HatchReady()
                    self.Status.Hatch = count > 0 and ("вылуплено: " .. count) or "жду готовые яйца"
                end

                -- Auto collect
                if settings.AutoCollect and now - lastCollect > 30 then
                    lastCollect = now
                    local ok2 = self:CollectEarnings()
                    self.Status.Collect = ok2 and "доход собран" or "ремоут не найден"
                end

                -- Treadmill wear + optional doff cycle
                if settings.AutoTreadmill and now - lastTreadmill > math.max(20, settings.TreadmillInterval or 60) then
                    lastTreadmill = now
                    self:WearTreadmill()
                    self.Status.Treadmill = "на дорожке"
                end
                if settings.AutoDoff and now - lastDoff > 5 then
                    lastDoff = now
                    if self:DoffTreadmill() then
                        self.Status.Treadmill = "сошли, ждём повторный AskWearStill"
                    end
                end

                -- Upgrades (treadmill + base)
                if (settings.AutoTreadmillUpgrade or settings.AutoBaseUpgrade) and now - lastTreadmillUpgrade > math.max(30, settings.UpgradeInterval or 90) then
                    lastTreadmillUpgrade = now
                    if settings.AutoTreadmillUpgrade then
                        local okTm = self:UpgradeTreadmill()
                        self.Status.Upgrades = okTm and "дорожка улучшена" or "дорожка: отклонено/максимум"
                    end
                    if settings.AutoBaseUpgrade then
                        local okBase = self:UpgradeBase()
                        self.Status.Upgrades = (self.Status.Upgrades or "upgrade") .. " • база: " .. (okBase and "улучшена" or "отклонено/максимум")
                    end
                end

                -- Best pets auto-wear
                if settings.AutoPetsBest and now - lastPets > 120 then
                    lastPets = now
                    local okPets, info = self:WearBestPets()
                    self.Status.Pets = okPets and ("лучшие питомцы (" .. tostring(info) .. ")") or ("питомцы: " .. tostring(info))
                end

                -- Trap neutralizer
                if settings.NeutralizeTraps and now - lastTraps > 3 then
                    lastTraps = now
                    local count = self:NeutralizeTraps()
                    self.Status.Traps = count > 0 and ("отключено ловушек: " .. count) or "ловушек нет"
                end

                -- Auto sell
                if (settings.AutoSellEggs or settings.AutoSellPets) and now - lastSell > math.max(3, settings.SellInterval or 10) then
                    lastSell = now
                    local soldEggs, soldPets, remotes = self:SellOnce()
                    if remotes == 0 then
                        self.Status.Sell = "Sell-ремоуты не найдены"
                    else
                        self.Status.Sell = string.format("яиц: %d, питомцев: %d (ремоутов %d)", soldEggs, soldPets, remotes)
                    end
                end
            end)
            if not ok then self.Status.Steal = "ошибка: " .. tostring(err) end
            -- Humanized loop delay: never a fixed robotic interval (BAC rate heuristics).
            local loopDelay = math.max(1.0, settings.StealDelay or 2)
            if settings.HumanizeDelays then loopDelay = loopDelay * (0.85 + math.random() * 0.4) end
            task.wait(loopDelay)
        end
    end)
end

function Automation:Destroy()
    self.Running = false
end

return Automation
]====]

M["modules/player.lua"] = [====[
-- MilfaCheatHUB • local player tweaks (stealth v0.5)
-- Speed without touching Humanoid.WalkSpeed (CFrame glide), jump, infinite jump,
-- noclip, glide click-TP, anti-AFK. BAC-safe by default.

local Player = {}
Player.__index = Player

function Player.new(config, stealth)
    local self = setmetatable({}, Player)
    self.Config = config
    self.Stealth = stealth
    self.Players = game:GetService("Players")
    self.UserInput = game:GetService("UserInputService")
    self.RunService = game:GetService("RunService")
    self.VirtualUser = game:GetService("VirtualUser")
    self.Player = self.Players.LocalPlayer
    self.Connections = {}
    self.Original = {}
    self:WatchRespawn()
    self:WatchStealthSpeed()
    return self
end

function Player:GetHumanoid()
    local character = self.Player.Character
    return character and character:FindFirstChildOfClass("Humanoid")
end

-- Classic mode: sets WalkSpeed/JumpPower (visible to client anticheat watchers).
-- Stealth mode: does nothing — speed comes from CFrame glide below.
function Player:ApplySpeed()
    local settings = self.Config.Settings
    if settings.StealthSpeed then
        if self.Stealth and self.Stealth.AntiCheat then
            self.Stealth.AntiCheat.EnableSpeedLock(nil)
        end
        return
    end
    local humanoid = self:GetHumanoid()
    if humanoid then
        humanoid.UseJumpPower = true
        humanoid.WalkSpeed = settings.WalkSpeed or 16
        humanoid.JumpPower = settings.JumpPower or 50
        -- Lock the value so the anticheat cannot reset it (rscripts method).
        if self.Stealth and self.Stealth.AntiCheat then
            self.Stealth.AntiCheat.EnableSpeedLock(settings.WalkSpeed or 16)
        end
    end
end

-- STEALTH SPEED: character glides via CFrame while the player holds movement.
-- Humanoid.WalkSpeed stays 16 so WalkSpeed-watchers never fire.
function Player:WatchStealthSpeed()
    if self.Connections.StealthSpeed then return end
    self.Connections.StealthSpeed = self.RunService.Heartbeat:Connect(function(deltaTime)
        local settings = self.Config.Settings
        if not settings.StealthSpeed then return end

        local character = self.Player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if not humanoid or not root or humanoid.Health <= 0 then return end

        local direction = humanoid.MoveDirection
        if direction.Magnitude < 0.05 then return end

        local speed = math.clamp(settings.StealthSpeedValue or 32, 16, 90)
        -- Humanized micro-jitter so movement is not perfectly linear.
        if settings.HumanizeDelays then
            speed = speed * (0.92 + math.random() * 0.16)
        end
        local step = direction * speed * deltaTime
        root.CFrame = root.CFrame + step
    end)
end

-- Re-apply speed/jump after respawn or character switch.
function Player:WatchRespawn()
    if self.Connections.Respawn then return end
    self.Connections.Respawn = self.Player.CharacterAdded:Connect(function()
        task.wait(0.6)
        pcall(function() self:ApplySpeed() end)
    end)
end

function Player:ResetSpeed()
    local settings = self.Config.Settings
    settings.WalkSpeed = 16
    settings.JumpPower = 50
    settings.StealthSpeed = false
    if self.Stealth and self.Stealth.AntiCheat then
        self.Stealth.AntiCheat.EnableSpeedLock(nil)
    end
    local humanoid = self:GetHumanoid()
    if humanoid then
        humanoid.UseJumpPower = true
        humanoid.WalkSpeed = 16
        humanoid.JumpPower = 50
    end
end

function Player:SetInfiniteJump(value)
    self.Config.Settings.InfiniteJump = value == true
    if value and not self.Connections.InfiniteJump then
        self.Connections.InfiniteJump = self.UserInput.JumpRequest:Connect(function()
            if not self.Config.Settings.InfiniteJump then return end
            local humanoid = self:GetHumanoid()
            if humanoid then
                pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end)
            end
        end)
    elseif not value and self.Connections.InfiniteJump then
        self.Connections.InfiniteJump:Disconnect()
        self.Connections.InfiniteJump = nil
    end
end

function Player:SetNoclip(value)
    self.Config.Settings.Noclip = value == true
    if value and not self.Connections.Noclip then
        self.Connections.Noclip = self.RunService.Stepped:Connect(function()
            if not self.Config.Settings.Noclip then return end
            local character = self.Player.Character
            if not character then return end
            for _, part in ipairs(character:GetChildren()) do
                if part:IsA("BasePart") and part.CanCollide then
                    part.CanCollide = false
                end
            end
        end)
    elseif not value and self.Connections.Noclip then
        self.Connections.Noclip:Disconnect()
        self.Connections.Noclip = nil
        local character = self.Player.Character
        if character then
            for _, part in ipairs(character:GetDescendants()) do
                if part:IsA("BasePart") then part.CanCollide = true end
            end
        end
    end
end

-- Click teleport now glides instead of a raw CFrame jump.
function Player:SetClickTP(value)
    self.Config.Settings.ClickTP = value == true
    if value and not self.Connections.ClickTP then
        self.Connections.ClickTP = self.UserInput.InputBegan:Connect(function(input, processed)
            if processed or input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
            if not self.Config.Settings.ClickTP then return end
            local mouse = self.Player:GetMouse()
            local target = mouse and mouse.Hit
            if target then
                if self.Stealth and self.Stealth.GlideTo then
                    self.Stealth.SafeTeleport = self.Config.Settings.SafeTeleport
                    self.Stealth.GlideSpeed = self.Config.Settings.GlideSpeed
                    task.spawn(function()
                        pcall(self.Stealth.GlideTo, self.Stealth, target.Position, {Height = 3})
                    end)
                else
                    local root = self.Player.Character and self.Player.Character:FindFirstChild("HumanoidRootPart")
                    if root then root.CFrame = CFrame.new(target.Position + Vector3.new(0, 3, 0)) end
                end
            end
        end)
    elseif not value and self.Connections.ClickTP then
        self.Connections.ClickTP:Disconnect()
        self.Connections.ClickTP = nil
    end
end

function Player:SetAntiAFK(value)
    self.Config.Settings.AntiAFK = value == true
    if value and not self.Connections.AntiAFK then
        self.Connections.AntiAFK = self.Player.Idled:Connect(function()
            if not self.Config.Settings.AntiAFK then return end
            pcall(function()
                self.VirtualUser:CaptureController()
                self.VirtualUser:ClickButton2(Vector2.new())
            end)
        end)
    elseif not value and self.Connections.AntiAFK then
        self.Connections.AntiAFK:Disconnect()
        self.Connections.AntiAFK = nil
    end
end

function Player:Destroy()
    for _, connection in pairs(self.Connections) do
        pcall(function() connection:Disconnect() end)
    end
    self.Connections = {}
    self.Config.Settings.InfiniteJump = false
    self.Config.Settings.Noclip = false
    self.Config.Settings.ClickTP = false
    self.Config.Settings.AntiAFK = false
    self:ResetSpeed()
end

return Player
]====]

M["modules/features.lua"] = [====[
-- MilfaCheatHUB • feature controller v0.4 (stealth)

local Features = {}
Features.__index = Features

function Features.new(config, ui, scanner, network, positions, esp, eggs, automation, player, rarity, alive, stealth)
    local self = setmetatable({}, Features)
    self.Config = config
    self.UI = ui
    self.Scanner = scanner
    self.Network = network
    self.Positions = positions
    self.ESP = esp
    self.Eggs = eggs
    self.Automation = automation
    self.Player = player
    self.Rarity = rarity
    self.Alive = alive
    self.Stealth = stealth
    self.Running = false
    self.FpsOriginal = {}
    return self
end

-- Glide wrapper used by every manual teleport button.
function Features:GlideTo(position, height)
    local stealth = self.Stealth
    if stealth and stealth.GlideTo and self.Config.Settings.SafeTeleport then
        stealth.SafeTeleport = true
        stealth.GlideSpeed = self.Config.Settings.GlideSpeed or 48
        task.spawn(function()
            pcall(stealth.GlideTo, stealth, position, {Height = height or 2.5})
        end)
        return
    end
    local root = self.Eggs:GetRoot()
    if root then root.CFrame = CFrame.new(position + Vector3.new(0, height or 2.5, 0)) end
end

function Features:SetFpsMode(enabled)
    local effectClasses = {
        ParticleEmitter = true,
        Trail = true,
        Beam = true,
        Smoke = true,
        Fire = true,
        Sparkles = true,
    }

    if enabled then
        local processed = 0
        for _, object in ipairs(workspace:GetDescendants()) do
            if effectClasses[object.ClassName] then
                self.FpsOriginal[object] = object.Enabled
                object.Enabled = false
            elseif object:IsA("BasePart") then
                self.FpsOriginal[object] = object.CastShadow
                object.CastShadow = false
            end
            processed = processed + 1
            if processed % 500 == 0 then task.wait() end
        end
    else
        local processed = 0
        for object, value in pairs(self.FpsOriginal) do
            if object and object.Parent then
                pcall(function()
                    if object:IsA("BasePart") then object.CastShadow = value
                    else object.Enabled = value end
                end)
            end
            processed = processed + 1
            if processed % 500 == 0 then task.wait() end
        end
        self.FpsOriginal = {}
    end
end

function Features:UpdateEggs()
    local settings = self.Config.Settings
    local records = self.Eggs:Scan()
    self.AllRecords = records

    local filtered = self.Eggs:Filter(records, {
        Rarities = settings.RarityFilter,
        MaxDistance = settings.MaxListDistance,
    })
    self.Eggs:Sort(filtered, settings.SortMode)
    self.FilteredRecords = filtered

    if self.EggStatus then
        self.EggStatus:Set(string.format("Всего объектов: %d  •  по фильтру: %d", #records, #filtered))
    end
    if self.EggList then
        self.EggList:Rebuild(filtered, {
            OnTeleport = function(record)
                if record.Position then
                    self:GlideTo(record.Position)
                end
            end,
            OnSteal = function(record)
                pcall(function() self.Automation:StealOne(record) end)
            end,
        })
    end
    if self.ESP.Enabled then
        local espRecords = settings.EspFilterOnly and filtered or records
        self.ESP:Refresh(espRecords, self.Scanner)
    end
    return records
end

function Features:RefreshStatuses()
    local status = self.Automation.Status
    if self.StealStatus then self.StealStatus:Set("Кража: " .. tostring(status.Steal or "—")) end
    if self.SellStatus then self.SellStatus:Set("Продажа: " .. tostring(status.Sell or "—")) end
    if self.HatchStatus then self.HatchStatus:Set("Вылупление: " .. tostring(status.Hatch or "—")) end
    if self.CollectStatus then self.CollectStatus:Set("Доход: " .. tostring(status.Collect or "—")) end
    if self.TreadmillStatus then self.TreadmillStatus:Set("Дорожка: " .. tostring(status.Treadmill or "—")) end
    if self.UpgradeStatus then self.UpgradeStatus:Set("Апгрейды: " .. tostring(status.Upgrades or "—")) end
    if self.PetsStatus then self.PetsStatus:Set("Питомцы: " .. tostring(status.Pets or "—")) end
    if self.TrapsStatus then self.TrapsStatus:Set("Ловушки: " .. tostring(status.Traps or "—")) end
end

-- Fast egg carry: zero hold time on the game's "CarryAreaEgg" ProximityPrompt.
-- Community-proven utility (l10scripts style): subscribe once, zero every prompt
-- both at enable-time and whenever the game shows a fresh one.
function Features:ApplyFastPrompt(enabled)
    local service = game:GetService("ProximityPromptService")
    local Players = game:GetService("Players")
    local localPlayer = Players.LocalPlayer

    if self._FastPromptConn then
        pcall(function() self._FastPromptConn:Disconnect() end)
        self._FastPromptConn = nil
    end

    if not enabled then return end

    local function zeroPrompt(prompt)
        pcall(function()
            if prompt and prompt:IsA("ProximityPrompt") and prompt.Name == "CarryAreaEgg" then
                prompt.HoldDuration = 0
            end
        end)
    end

    -- Existing prompts in the world right now.
    pcall(function()
        for _, descendant in ipairs(workspace:GetDescendants()) do
            if descendant:IsA("ProximityPrompt") then zeroPrompt(descendant) end
        end
    end)

    -- Fresh prompts shown later (hold begins -> zero before progress starts).
    self._FastPromptConn = service.PromptButtonHoldBegan:Connect(function(prompt, player)
        if player == localPlayer then zeroPrompt(prompt) end
    end)
end

-- Soft anti-teleport: disconnect the client handlers of RE/RigSync/Refresh so
-- the server cannot rubber-band our glides back. Reversible via Disable when
-- the executor supports it; falls back to Disconnect otherwise.
function Features:ApplyRigSyncCut(enabled)
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local packages = ReplicatedStorage:FindFirstChild("Packages")
    local networking = packages and packages:FindFirstChild("Networking")
    local remote = networking and networking:FindFirstChild("RE/RigSync/Refresh")
    if not remote then
        if self.Stealth then self.Stealth.Note("RigSync: remote RE/RigSync/Refresh не найден") end
        return
    end

    -- Restore previously disabled connections first.
    if self._RigSyncConns then
        for _, connection in ipairs(self._RigSyncConns) do
            pcall(function() connection:Enable() end)
        end
        self._RigSyncConns = nil
    end

    if not enabled then return end

    if type(getconnections) ~= "function" then
        if self.Stealth then self.Stealth.Note("RigSync: getconnections не поддерживается экзекьютором") end
        return
    end

    local ok, connections = pcall(getconnections, remote.OnClientEvent)
    if not ok or type(connections) ~= "table" then
        if self.Stealth then self.Stealth.Note("RigSync: не удалось получить connections: " .. tostring(connections)) end
        return
    end

    local patched = 0
    local stored = {}
    for _, connection in ipairs(connections) do
        local disabled = pcall(function() connection:Disable() end)
        if not disabled then
            disabled = pcall(function() connection:Disconnect() end)
        end
        if disabled then
            patched = patched + 1
            stored[#stored + 1] = connection
        end
    end
    self._RigSyncConns = stored
    if self.Stealth then self.Stealth.Note("RigSync: отключено обработчиков: " .. patched) end
end

function Features:Build()
    local colors = self.Config.Colors
    local settings = self.Config.Settings

    local eggsTab = self.UI:CreateTab("Яйца", "EGG", colors.World)
    local autoTab = self.UI:CreateTab("Авто", "BOT", colors.Combat)
    local espTab = self.UI:CreateTab("ESP", "ESP", colors.ESP)
    local playerTab = self.UI:CreateTab("Игрок", "PLR", colors.Player)
    local pointsTab = self.UI:CreateTab("Точки", "POS", colors.Movement)
    local systemTab = self.UI:CreateTab("Система", "SYS", colors.Misc)

    -- ============================== ЯЙЦА ==============================
    self.UI:AddHeading(eggsTab, "Динамический сканер яиц")
    self.EggStatus = self.UI:AddText(eggsTab, "Состояние", "Первый скан запускается после открытия GUI")
    self.UI:AddButton(eggsTab, "Обновить список яиц", function()
        local ok, result = pcall(function() return self:UpdateEggs() end)
        if not ok then self.EggStatus:Set("Ошибка сканера: " .. tostring(result)) end
    end)

    self.RarityChips = self.UI:AddChips(eggsTab, "Фильтр редкости (список, ESP-фильтр и автокража)",
        self.Rarity.Ids(), settings.RarityFilter, function(list)
            settings.RarityFilter = list
        end)

    self.MaxDistanceSlider = self.UI:AddSlider(eggsTab, "Макс. дистанция списка", 0, 2000, settings.MaxListDistance, " st", function(value)
        settings.MaxListDistance = value
    end)
    self.UI:AddDropdown(eggsTab, "Сортировка списка", {"rarity", "distance"}, settings.SortMode, function(option)
        settings.SortMode = option
        if self.FilteredRecords then
            self.Eggs:Sort(self.FilteredRecords, option)
            pcall(function() self:UpdateEggs() end)
        end
    end)
    self.UI:AddToggle(eggsTab, "Автообновление списка", settings.EggListAutoRefresh, function(value)
        settings.EggListAutoRefresh = value
    end)

    self.UI:AddSection(eggsTab, "Список яиц")
    self.EggList = self.UI:CreateEggList(eggsTab, self.Rarity)
    self.UI:AddText(eggsTab, "Кнопки", "TP — телепорт к яйцу, СТЛ — украсть это яйцо (TP + Carry + Place).")
    self.UI:AddText(eggsTab, "Важно", "Прямого ремоута кражи у игроков в игре нет — автокража работает с полевыми яйцами биомов и промптами. FirstAreaSlotKey подставляется автоматически.")

    -- ============================== АВТО ==============================
    self.UI:AddHeading(autoTab, "Автокража")
    self.StealStatus = self.UI:AddText(autoTab, "Кража", "выключено")
    self.UI:AddToggle(autoTab, "Автокража включена", settings.AutoSteal, function(value)
        settings.AutoSteal = value
        if not value then self.Automation.Status.Steal = "выключено" end
    end)
    self.UI:AddDropdown(autoTab, "Приоритет цели", {"rarity", "distance"}, settings.StealPriority, function(option)
        settings.StealPriority = option
    end)
    self.UI:AddSlider(autoTab, "Радиус поиска целей", 50, 2000, settings.StealRadius, " st", function(value)
        settings.StealRadius = value
    end)
    self.UI:AddSlider(autoTab, "Пауза между попытками", 0.5, 10, settings.StealDelay, " c", function(value)
        settings.StealDelay = value
    end)
    self.UI:AddToggle(autoTab, "Телепорт к цели (иначе ходьба)", settings.StealTeleport, function(value)
        settings.StealTeleport = value
    end)
    self.UI:AddToggle(autoTab, "Нести домой и ставить", settings.AutoReturn, function(value)
        settings.AutoReturn = value
    end)
    self.UI:AddToggle(autoTab, "Сбрасывать яйцо из рук", settings.AutoDrop, function(value)
        settings.AutoDrop = value
    end)
    self.UI:AddToggle(autoTab, "Автопостановка яиц из инвентаря", settings.AutoPlace, function(value)
        settings.AutoPlace = value
    end)

    self.UI:AddSection(autoTab, "Автоматика базы")
    self.HatchStatus = self.UI:AddText(autoTab, "Вылупление", "выключено")
    self.UI:AddToggle(autoTab, "Автовылупление (GrowingEggs + AskHatch)", settings.AutoHatch, function(value)
        settings.AutoHatch = value
        if not value then self.Automation.Status.Hatch = "выключено" end
    end)
    self.CollectStatus = self.UI:AddText(autoTab, "Доход", "выключено")
    self.UI:AddToggle(autoTab, "Автосбор дохода (AskCollect)", settings.AutoCollect, function(value)
        settings.AutoCollect = value
        if value then self.Automation.Status.Collect = "включено" end
    end)
    self.UI:AddToggle(autoTab, "Дорожка: вставать (AskWearStill)", settings.AutoTreadmill, function(value)
        settings.AutoTreadmill = value
    end)
    self.TreadmillStatus = self.UI:AddText(autoTab, "Дорожка", "выключено")
    self.UI:AddToggle(autoTab, "Дорожка: сходить каждые 5с (AskDoff)", settings.AutoDoff, function(value)
        settings.AutoDoff = value
    end)

    self.UI:AddSection(autoTab, "Автоулучшения")
    self.UpgradeStatus = self.UI:AddText(autoTab, "Апгрейды", "выключено")
    self.UI:AddToggle(autoTab, "Улучшать дорожку (AskTierRaise)", settings.AutoTreadmillUpgrade, function(value)
        settings.AutoTreadmillUpgrade = value
    end)
    self.UI:AddToggle(autoTab, "Улучшать базу (AskBaseTierRaise)", settings.AutoBaseUpgrade, function(value)
        settings.AutoBaseUpgrade = value
    end)
    self.UI:AddSlider(autoTab, "Пауза между апгрейдами", 30, 600, settings.UpgradeInterval, " c", function(value)
        settings.UpgradeInterval = value
    end)

    self.UI:AddSection(autoTab, "Питомцы и защита")
    self.PetsStatus = self.UI:AddText(autoTab, "Питомцы", "выключено")
    self.UI:AddToggle(autoTab, "Надевать лучших питомцев (PenRoster)", settings.AutoPetsBest, function(value)
        settings.AutoPetsBest = value
    end)
    self.UI:AddSlider(autoTab, "Сколько питомцев надевать", 1, 8, settings.PetSlots, "", function(value)
        settings.PetSlots = value
    end)
    self.TrapsStatus = self.UI:AddText(autoTab, "Ловушки", "выключено")
    self.UI:AddToggle(autoTab, "Отключать чужие ловушки (__DEBRIS)", settings.NeutralizeTraps, function(value)
        settings.NeutralizeTraps = value
    end)

    self.UI:AddSection(autoTab, "Автопродажа с фильтром редкости")
    self.SellStatus = self.UI:AddText(autoTab, "Продажа", "выключено")
    self.UI:AddToggle(autoTab, "Продавать яйца", settings.AutoSellEggs, function(value)
        settings.AutoSellEggs = value
        if not value then self.Automation.Status.Sell = "выключено" end
    end)
    self.UI:AddToggle(autoTab, "Продавать питомцев", settings.AutoSellPets, function(value)
        settings.AutoSellPets = value
        if not value then self.Automation.Status.Sell = "выключено" end
    end)
    self.UI:AddChips(autoTab, "НЕ продавать эти редкости (остальное продаётся)",
        self.Rarity.Ids(), settings.KeepRarities, function(list)
            settings.KeepRarities = list
        end)
    self.UI:AddSlider(autoTab, "Пауза между продажами", 3, 60, settings.SellInterval, " c", function(value)
        settings.SellInterval = value
    end)

    self.UI:AddSection(autoTab, "Сервер и события")
    self.UI:AddToggle(autoTab, "Смена сервера при пустых целях", settings.AutoServerHop, function(value)
        settings.AutoServerHop = value
    end)
    self.UI:AddButton(autoTab, "Сменить сервер сейчас", function()
        self.Automation:ServerHop()
    end)
    self.UI:AddButton(autoTab, "Скормить яйцо монстру (событие)", function()
        local ok, info = self.Automation:FeedMonster()
        if not ok then self.StealStatus:Set("Монстр: " .. tostring(info or "не найден")) end
    end)

    -- ============================== ESP ==============================
    self.UI:AddHeading(espTab, "Неоновый Egg ESP")
    self.EspStatus = self.UI:AddText(espTab, "ESP", "Выключен")
    self.UI:AddToggle(espTab, "Показывать яйца", settings.EggESP, function(value)
        settings.EggESP = value
        self.ESP:SetEnabled(value)
        self.EspStatus:Set(value and "Включён • автообновление" or "Выключен")
        if value then pcall(function() self:UpdateEggs() end) end
    end)
    self.UI:AddToggle(espTab, "Цвет и редкость в подписи", settings.ShowRarity, function(value)
        settings.ShowRarity = value
    end)
    self.UI:AddToggle(espTab, "Показывать дистанцию", settings.ShowDistance, function(value)
        settings.ShowDistance = value
    end)
    self.UI:AddToggle(espTab, "ESP только по фильтру редкости", settings.EspFilterOnly, function(value)
        settings.EspFilterOnly = value
    end)
    self.UI:AddSlider(espTab, "Дальность ESP", 200, 5000, settings.EspMaxDistance, " st", function(value)
        settings.EspMaxDistance = value
    end)

    -- ============================== ИГРОК ==============================
    self.UI:AddHeading(playerTab, "Персонаж (стелс по умолчанию)")
    self.SpeedStatus = self.UI:AddText(playerTab, "Режим скорости", "Стелс: WalkSpeed остаётся 16, движение через CFrame")
    self.UI:AddToggle(playerTab, "СТЕЛС-скорость (не трогает WalkSpeed)", settings.StealthSpeed, function(value)
        settings.StealthSpeed = value
        self.SpeedStatus:Set(value and "Стелс: WalkSpeed = 16, движение через CFrame" or "Классика: прямой WalkSpeed (риск BAC)")
        if not value then self.Player:ApplySpeed() end
    end)
    self.UI:AddSlider(playerTab, "Стелс-скорость, ст/с (держи < 60)", 16, 90, settings.StealthSpeedValue, "", function(value)
        settings.StealthSpeedValue = value
    end)
    self.UI:AddSlider(playerTab, "Классическая скорость (WalkSpeed)", 16, 250, settings.WalkSpeed, "", function(value)
        settings.WalkSpeed = value
        self.Player:ApplySpeed()
        if self.Stealth and self.Stealth.AntiCheat and not settings.StealthSpeed then
            self.Stealth.AntiCheat.EnableSpeedLock(value)
        end
    end)
    self.UI:AddSlider(playerTab, "Прыжок (JumpPower)", 50, 250, settings.JumpPower, "", function(value)
        settings.JumpPower = value
        self.Player:ApplySpeed()
    end)
    self.UI:AddButton(playerTab, "Сбросить скорость и прыжок", function()
        self.Player:ResetSpeed()
    end)
    self.UI:AddToggle(playerTab, "Бесконечный прыжок", settings.InfiniteJump, function(value)
        self.Player:SetInfiniteJump(value)
    end)
    self.UI:AddToggle(playerTab, "Noclip (сквозь стены)", settings.Noclip, function(value)
        self.Player:SetNoclip(value)
    end)
    self.UI:AddToggle(playerTab, "Телепорт кликом (ЛКМ)", settings.ClickTP, function(value)
        self.Player:SetClickTP(value)
    end)
    self.UI:AddToggle(playerTab, "Anti-AFK (не кикать за простой)", settings.AntiAFK, function(value)
        self.Player:SetAntiAFK(value)
    end)

    -- ============================== ТОЧКИ ==============================
    self.UI:AddHeading(pointsTab, "Живые позиции карты")
    self.PointStatus = self.UI:AddText(pointsTab, "Результат", self.Positions:Summary())
    self.PointList = self.UI:AddText(pointsTab, "Первые точки", self.Positions:ListText(3))
    self.UI:AddButton(pointsTab, "Пересканировать точки", function()
        self.PointStatus:Set(self.Positions:Summary())
        self.PointList:Set(self.Positions:ListText(3))
    end)
    self.UI:AddButton(pointsTab, "Телепорт на базу", function()
        local home = self.Positions:GetHome()
        if home then
            self:GlideTo(home, 3)
        end
    end)

    -- ============================== СИСТЕМА ==============================
    self.UI:AddHeading(systemTab, "СТЕЛС CALM (v0.6.2)")
    local mountKind = self.Stealth and tostring(self.Stealth.MountKind) or "неизвестно"
    local mountNote = (mountKind == "PlayerGui")
        and "PlayerGui-фолбэк с камуфляж-именем (игровые скрипты его видят!)"
        or "Скрытый маунт (gethui/CoreGui) — невидим игровым сканерам"
    self.StealthStatus = self.UI:AddText(systemTab, "Маунт GUI: " .. mountKind, mountNote)
    self.UI:AddToggle(systemTab, "Безопасные телепорты (glide)", settings.SafeTeleport, function(value)
        settings.SafeTeleport = value
        if self.Stealth then self.Stealth.SafeTeleport = value end
    end)
    self.UI:AddSlider(systemTab, "Скорость glide, ст/с (держи < 70)", 20, 100, settings.GlideSpeed, "", function(value)
        settings.GlideSpeed = value
        if self.Stealth then self.Stealth.GlideSpeed = value end
    end)
    self.UI:AddToggle(systemTab, "Человеческие задержки (джиттер)", settings.HumanizeDelays, function(value)
        settings.HumanizeDelays = value
    end)
    self.UI:AddToggle(systemTab, "Подробные логи в консоль (ДЕРЖИ ВЫКЛ)", settings.DebugLogs, function(value)
        settings.DebugLogs = value
        if self.Stealth then self.Stealth.Debug = value end
    end)
    self.UI:AddText(systemTab, "Почему логи опасны", "Античит читает консоль через LogService (GetLogHistory). Любой print со словами Cheat/Hack/GUI — возможный триггер. v0.6.2 при загрузке печатает ТОЛЬКО голый номер версии, без слов.")
    self.UI:AddText(systemTab, "GUI при загрузке", "GUI появляется сразу и маунтится скрыто (gethui/CoreGui) — невидим игровым сканерам. Тихий режим (без GUI) — опция HeadlessLoad: 3 пальца / RightControl / чат /e mh.")

    -- ================== ОБХОД АНТИЧИТА (BAC, opt-in) ==================
    -- Полеarm данные: v0.4.1 хук namecall -> BAC-4513, v0.5.0 freeze/masking -> BAC-2516.
    -- Рабочие хабы (boblo и др.) бегают ВООБЩЕ без хуков. Поэтому GHOST по умолчанию.
    local AC = self.Stealth and self.Stealth.AntiCheat or nil
    if AC then
        local function acStatusText()
            return AC:Summary()
        end
        self.ACStatus = self.UI:AddText(systemTab, "Режим BAC", acStatusText())
        self.UI:AddToggle(systemTab, "АГРЕССИВНЫЙ обход BAC (не рекомендуется: палятся хуки)", settings.BacAutoBypass, function(value)
            settings.BacAutoBypass = value
            task.spawn(function()
                -- ВАЖНО: Init определён через ТОЧКУ — вызов через двоеточие
                -- сдвигал бы аргументы (aggressive = таблица настроек = truthy).
                AC.Init(self.Stealth, settings, value)
                if self.ACStatus then self.ACStatus:Set(acStatusText()) end
            end)
        end)
        self.UI:AddToggle(systemTab, "  [агрессивный] Блокировать клиентский Kick", settings.BlockKick, function(value)
            settings.BlockKick = value
            if self.Stealth then self.Stealth.BlockKick = value end
        end)
        self.UI:AddToggle(systemTab, "  [агрессивный] Заморозка состояний AC (getgc)", settings.FreezeACStates, function(value)
            settings.FreezeACStates = value
        end)
        self.UI:AddToggle(systemTab, "  [агрессивный] Ослепить сэмплер скорости", settings.BlindSamplers, function(value)
            settings.BlindSamplers = value
        end)
        self.UI:AddToggle(systemTab, "  [агрессивный] Маскировать Http-пробы (риск BAC-2516)", settings.MaskHttpProbes, function(value)
            settings.MaskHttpProbes = value
        end)
        self.UI:AddButton(systemTab, "Применить обход заново (переинициализация)", function()
            task.spawn(function()
                AC.Init(self.Stealth, settings, settings.BacAutoBypass == true)
                if self.ACStatus then self.ACStatus:Set(acStatusText()) end
            end)
        end)
    end

    -- ============ ИГРОВЫЕ ПОМОЩНИКИ (проверено сообществом) ============
    self.UI:AddHeading(systemTab, "Игровые помощники")
    self.UI:AddToggle(systemTab, "Быстрый перенос яйца (HoldDuration=0 у CarryAreaEgg)", settings.FastPrompt, function(value)
        settings.FastPrompt = value
        task.spawn(function() self:ApplyFastPrompt(value) end)
    end)
    self.UI:AddToggle(systemTab, "Отключить RigSync-ресеты (мягкий анти-ТП)", settings.RigSyncCut, function(value)
        settings.RigSyncCut = value
        task.spawn(function() self:ApplyRigSyncCut(value) end)
    end)
    self.UI:AddSlider(systemTab, "Лимит AskHatch за такт", 1, 8, settings.MaxHatchPerTick, "", function(value)
        settings.MaxHatchPerTick = value
    end)
    self.UI:AddButton(systemTab, "PANIC: убрать все следы (GUI, ESP, скорость)", function()
        local stealth = self.Stealth
        local registry = stealth and stealth.Registry
        if registry and registry.Panic then
            registry.Panic()
        end
    end)
    self.UI:AddButton(systemTab, "Диагностика в консоль (F9)", function()
        local stealth = self.Stealth
        local registry = stealth and stealth.Registry
        if registry and registry.Diag then
            registry.Diag()
            self.StealthStatus:Set("Диагностика выведена в консоль F9")
        end
    end)
    self.UI:AddText(systemTab, "Как не словить BAC", "CALM-режим: хуки ВЫКЛ, логи без слов, маунт скрытый, при загрузке печатается только номер версии. BAC-7517 = детект хуков/спая; скан цикл ~5с. Glide < 70, стелс-скорость < 60. Прямые TP с яйцом сервер отклоняет — только glide-ходьба.")

    self.UI:AddHeading(systemTab, "Диагностика MilfaCheatHUB")
    self.NetworkStatus = self.UI:AddText(systemTab, "Networking", self.Network:Summary())
    self.UI:AddButton(systemTab, "Проверить известные Remotes", function()
        self.NetworkStatus:Set(self.Network:Summary())
    end)
    self.UI:AddButton(systemTab, "Найти Sell-ремоуты", function()
        local remotes = self.Eggs:FindSellRemotes()
        local lines = {}
        for _, remote in ipairs(remotes) do
            lines[#lines + 1] = remote.ClassName .. " " .. remote.Name
        end
        self.NetworkStatus:Set(#lines > 0 and ("Найдено: " .. table.concat(lines, ", ")) or "Sell-ремоуты не найдены")
    end)
    self.UI:AddButton(systemTab, "Дамп всех Remotes в консоль (F9)", function()
        local folder = self.Network:GetFolder()
        local count = 0
        if folder then
            for _, instance in ipairs(folder:GetDescendants()) do
                if instance:IsA("RemoteFunction") or instance:IsA("RemoteEvent") then
                    print("[mh] " .. instance.ClassName .. " " .. instance.Name)
                    count = count + 1
                end
            end
        end
        print("[mh] Всего: " .. count)
    end)
    self.FpsStatus = self.UI:AddText(systemTab, "Производительность", "Обычный режим")
    self.UI:AddToggle(systemTab, "Лёгкий FPS-режим", false, function(value)
        self.Config.Settings.FpsMode = value
        self.FpsStatus:Set(value and "Применяем настройки..." or "Восстанавливаем настройки...")
        self:SetFpsMode(value)
        self.FpsStatus:Set(value and "Эффекты и тени временно выключены" or "Настройки восстановлены")
    end)
    self.UI:AddText(
        systemTab,
        "Сборка " .. self.Config.Version,
        "CALM: при загрузке печатается только номер версии (LogService читается античитом), рандомный ключ реестра без сигнатур, скрытый маунт GUI, GUI появляется сразу. 50+ функций сохранены."
    )
end

function Features:Start()
    if self.Running then return end
    self.Running = true

    task.spawn(function()
        task.wait(0.5)
        pcall(function() self:UpdateEggs() end)
        while self.Running and self.Alive() do
            local settings = self.Config.Settings
            if settings.EggESP or settings.EggListAutoRefresh then
                pcall(function() self:UpdateEggs() end)
            end
            pcall(function() self:RefreshStatuses() end)
            task.wait(math.max(1.5, settings.RefreshSeconds or 3))
        end
    end)

    self.Automation:Start(self.Alive)
end

function Features:Destroy()
    self.Running = false
    self.Automation:Destroy()
    self.ESP:SetEnabled(false)
    self.Player:Destroy()
    pcall(function() self:ApplyFastPrompt(false) end)
    pcall(function() self:ApplyRigSyncCut(false) end)
    if self.Config.Settings.FpsMode then
        self.Config.Settings.FpsMode = false
        self:SetFpsMode(false)
    end
end

return Features
